class Mitarbeiter:
    def __init__(self, gehalt: int) -> None:
        self.gehalt = gehalt

    def monatskosten(self) -> int:
        return self.gehalt

class Manager(Mitarbeiter):
    def __init__(self, gehalt: int, team: int) -> None:
        super().__init__(gehalt)
        self.team = team

    def monatskosten(self) -> int:
        return super().monatskosten() + 150 * self.team

summe = 0
for person in [Mitarbeiter(3600), Mitarbeiter(4200), Manager(5800, 2)]:
    summe += person.monatskosten()
print(summe)

from abc import ABC, abstractmethod

class Tier(ABC):
    @abstractmethod
    def laut(self) -> str: ...

    def vorstellen(self) -> str:
        return "Ich sage " + self.laut()

class Hund(Tier):
    def laut(self) -> str:
        return "Wuff"

class Katze(Tier):
    pass

print(Hund().vorstellen())
print(Katze().vorstellen())
